style.css:
@-moz-document domain("numo.nl") {
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  }

  body {
    background-color: #f4f4f4;
    color: #333;
    line-height: 1.6;
    padding: 20px;
    font-size: 16px;
    animation: fadeIn 2s ease-out forwards;
  }

  /* Animaties */
  @keyframes fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes slideIn {
    from {
      transform: translateX(-100%);
    }
    to {
      transform: translateX(0);
    }
  }

  @keyframes scaleUp {
    from {
      transform: scale(0.9);
      opacity: 0;
    }
    to {
      transform: scale(1);
      opacity: 1;
    }
  }

  /* Hoofdstructuur */
  header {
    background-color: #0066cc;
    color: #fff;
    padding: 40px 20px;
    text-align: center;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    animation: slideIn 1.5s ease-out forwards;
  }

  header h1 {
    font-size: 3em;
    font-weight: bold;
    margin: 0;
    text-transform: uppercase;
  }

  nav {
    background-color: #003366;
    display: flex;
    justify-content: center;
    padding: 15px 0;
    border-radius: 5px;
    animation: slideIn 1.5s ease-out forwards;
  }

  nav a {
    color: #fff;
    text-decoration: none;
    padding: 15px 25px;
    font-size: 1.2em;
    transition: background-color 0.3s, transform 0.3s;
    margin: 0 10px;
    border-radius: 5px;
  }

  nav a:hover {
    background-color: #0055a5;
    transform: scale(1.05);
  }

  /* Secties */
  section {
    padding: 60px 0;
    text-align: center;
    animation: fadeIn 2s ease-out forwards;
    max-width: 1200px;
    margin: 0 auto;
  }

  section h2 {
    font-size: 2.8em;
    margin-bottom: 20px;
    color: #333;
  }

  section p {
    font-size: 1.2em;
    max-width: 800px;
    margin: 0 auto;
    line-height: 1.6;
    opacity: 0;
    animation: fadeIn 2.5s ease-out forwards;
    color: #555;
  }

  /* Cards voor content */
  .card {
    background-color: #fff;
    border-radius: 15px;
    box-shadow: 0 6px 12px rgba(0, 0, 0, 0.1);
    margin: 20px;
    padding: 30px;
    text-align: left;
    width: 280px;
    transition: transform 0.3s, box-shadow 0.3s;
    opacity: 0;
    animation: scaleUp 2s ease-out forwards;
  }

  .card:hover {
    transform: translateY(-10px);
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  }

  .card h3 {
    font-size: 1.8em;
    color: #333;
    margin-bottom: 15px;
  }

  .card p {
    font-size: 1.1em;
    color: #666;
    line-height: 1.5;
  }

  /* Footer */
  footer {
    background-color: #003366;
    color: #fff;
    padding: 20px 0;
    text-align: center;
    margin-top: 40px;
    animation: fadeIn 2s ease-out forwards;
    border-radius: 10px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  }

  footer a {
    color: #fff;
    text-decoration: none;
    font-size: 1.2em;
  }

  footer a:hover {
    text-decoration: underline;
  }

  footer p {
    margin-top: 15px;
    font-size: 1.1em;
    color: #ccc;
  }
}
